(\cite{Guy}, Pages 71, 74)
\begin{enumerate}[(1)]
\item
An integer $n$ is called \textit{perfect} if it is equal to the sum of its proper divisors, i.e.:
\begin{equation}
\delta(n)=2
\end{equation}
\item
An integer is called \textit{abundant} if it is smaller than the sum of its proper divisors, i.e.:
\begin{equation}
\delta(n)>2.
\end{equation}
\item
An integer is called \textit{deficient} if it is greater than the sum of its proper divisors, i.e.:
\begin{equation}
\delta(n)<2.
\end{equation}
\item
An abundant integer is called \textit{quasi-perfect} if the sum of its proper divisors is greater than itself by one, i.e.:
\begin{equation}
D(n)=2n+1.
\end{equation}
\item
A deficient integer is called \textit{almost perfect} if the sum of its proper divisors is smaller than itself by one, i.e.:
\begin{equation}
D(n)=2n-1.
\end{equation}
\end{enumerate}

\label{k=1}
Let $p$ be a prime, $P_i$ an even perfect number and $k$ a positive integer such that:
\begin{equation}\label{eq:perfect}
P_i+1=p^k.
\end{equation} 
Then $k=1$.

\label{perfect+1}
Using GAP \cite{GAP}, we found $4$ solutions for \eqref{eq:perfect}: 
\begin{equation}\label{Mersenne prime}
P_i\in \{P_1, P_2, P_5, P_7\}.
\end{equation}
They were obtained by checking the first $39$ even perfect numbers.

\label{def:functions}
Given a group $G$, we define the following: 
\begin{equation}
D(G)=\sum_{N\triangleleft G}|N|
\end{equation} 
and 
\begin{equation}
\delta(G) = \frac{D(G)}{|G|}.
\end{equation}

\label{sigma:cyclic}
For a cyclic finite group $C_n$, the following hold:
\begin{equation}\label{D}
D(C_n)=D(n)
\end{equation} 
and
\begin{equation}\label{delta}
\delta(C_n)=\delta(n).
\end{equation}

The following hold:
\begin{enumerate}[(1)]
\item
$\delta(G)>1$, for all $G\neq \{1\}$;
\item
$\delta(G/N)\leq \delta(G),$ for all $N \lhd G$;
\item
$D$, $\delta$ are multiplicative functions:
$$
\text{If }G_1, G_2 \text{ groups such that }\gcd(|G_1|,|G_2|)=1, \text{then }
$$
\begin{equation}
D(G_1\times G_2)=D(G_1)D(G_2)
\end{equation}
\begin{equation}
\delta(G_1\times G_2)=\delta(G_1)\delta(G_2)
\end{equation}
\end{enumerate}

Let $G$ be a group.
\begin{enumerate}[(1)]
\item
$G$ is called \textit{quasi-Leinster} if 
\begin{equation}
D(G)=2|G|+1.
\end{equation}
\item
$G$ is called \textit{almost Leinster} if 
\begin{equation}
D(G)=2|G|-1.
\end{equation}
\end{enumerate}

\label{prop:ZM}
The presentation of ZM-groups is given by:
\begin{equation}\label{eq:ZM}
ZM(m,n,r)=\langle a, b\mid a^m=b^n=1, b^{-1}ab=a^r\rangle,
\end{equation}
where the triplet $(m,n,r)\in(\mathbb{N}^*)^3$ satisfies the following conditions:
\begin{equation}\label{eq:mnr}
\begin{cases}
\gcd(m,n)=\gcd(m,r-1)=1,\\
r^n\equiv 1 \pmod m
\end{cases}
\end{equation}

According to \cite[Theorem 5.7]{Medts}, the value of $D(ZM(m,n,r))$ is given by:
\begin{equation}\label{eq:sigmaZMN}
D(ZM(m,n,r))=mn\sum_{n_1|n}\frac{\delta(\gcd(m,r^{n_1}-1))}{n_1}.
\end{equation}
Assume that $m$ is prime, and let $d$ be the order of $r$ modulo $m$. According to \cite[Corollary 5.9.]{Medts}, equation \eqref{eq:sigmaZMN} becomes:
\begin{equation}
D(ZM(m,n,r))=mD(n)+D\left(\frac{n}{d}\right).
\end{equation}
Suppose further that $n=d$. It follows that:
\begin{equation}\label{md}
D(ZM(m,n,r))=mD(n)+1.
\end{equation} 
If we assume that $ZM(m,n,r)$ is quasi-Leinster, it follows from Lemma \ref{ZMmnorder} that: $$D(ZM(m,n,r))=2mn+1,$$ which, using \eqref{md}, implies $D(n)=2n$, i.e. $n$ is perfect.
On the other hand, it follows from \eqref{eq:mnr}, that 
\begin{equation}\label{r}
r\not\equiv 1\pmod{m}\text{ and }r\not\equiv 0\pmod{m}.
\end{equation} since $m$ is prime, it follows that the order of $r$ modulo $m$ is $m-1$. Since we have assumed that the order of $r$ is $n$, $m-1=n$, or, equivalently $m=n+1$, which has solutions, according to Example \ref{perfect+1}. Any $r\in\{2,\dots,m-1\}$ satisfies the conditions.

\label{prop:affine}
There is a bijection between the subgroups of $\mathbb{F}_q^*$ and the non-trivial normal subgroups of $\operatorname{Aff}(\mathbb{F}_q)$, namely
$$H\leq \mathbb{F}_q^*\mapsto N_H=\begin{pmatrix}
H & \mathbb{F}_q\\
0 & 1
\end{pmatrix}=\left\{\begin{pmatrix}
a & b\\
0 & 1
\end{pmatrix}: a\in H, b\in \mathbb{F}_q\right\}\lhd \operatorname{Aff}(\mathbb{F}_q).$$

\label{NDn}
The normal subgroups of $D_{2n}$ are given by:
\begin{numcases}{N(D_{2n})=}\{D_{2n}\}\cup\{\langle r^d\rangle: d|n\}, & n\text{ odd} \label{odd}\\
\{D_{2n}\}\cup\{\langle r^d\rangle: d|n\}\cup \{\langle r^2, s\rangle, \langle r^2,rs\rangle\}, & n\text{ even} \label{even}.
\end{numcases}
In particular, there is at most one normal subgroup per index in $D_{2n}$ except for three normal subgroups $\langle r\rangle$, $\langle r^2, s\rangle$, $\langle r^2,rs\rangle$ of index $2$ when $n$ is even.

If we assume that $D_{2n}$ is almost/quasi-/Leinster, we get 
\begin{equation}\label{dihl}
D(D_{2n})=4n+a, a\in\{-1,0,1\}.
\end{equation}
We compute the value for $D(D_{2n})$, distinguishing two cases based on the parity of $n$:
\begin{description}
\item[$n$ odd.]
Using \eqref{odd} from Lemma \ref{NDn}, together with \eqref{dihl}, we get 
\begin{equation}\label{d2nodd}
2\cdot 2n+a=2n+D(n), a\in\{-1,0,1\},    
\end{equation}
which is equivalent to $D(n)=2n\pm a$, i.e. $n$ being almost/quasi-/perfect. 
\item[$n$ even.]
Again, using \eqref{dihl} and Lemma \ref{NDn}, we get: 
$4n+D(n)=4n+ a, a\in\{-1,0,1\}$, which has no solution.
\end{description}

\label{ndic}
The normal subgroups of $\operatorname{Dic}_{4n}$ are given by:
\begin{numcases}
{N(\operatorname{Dic}_{4n})=}
{\operatorname{Dic}_{4n}}\cup\{\langle a^d\rangle: d|2n\}, & n\text{ odd} \label{dodd}\\
{\operatorname{Dic}_{4n}}\cup\{\langle a^d\rangle: d|2n\}\cup \{\langle a^2, ax\rangle, \langle a^2, a^2x\rangle, & n\text{ even} \label{deven}.
\end{numcases}

If $\operatorname{Dic}_{4n}$ is almost/quasi-/Leinster, we get 
\begin{equation}\label{dicn}
D(\operatorname{Dic}_{4n})=8n + a, a\in\{-1,0,1\}
\end{equation}
Using lemma \ref{ndic}, we compute $D(\operatorname{Dic}_{4n})$ based on the parity of $n$.
\begin{description}
\item[$n$ even.]
In this case, it follows from \eqref{deven}, that $D(\operatorname{Dic}_{4n})=D(2n)+8n$. Together with \eqref{dicn}, we get $D(2n)+8n=8n + a, a\in\{-1,0,1\}$, which has no solution.
\item[$n$ odd.]
In this case $D(\operatorname{Dic}_{4n})=D(2n)+4n$. It follows that $D(2n)+4n=8n+a, a\in\{-1,0,1\}$, i.e.: 
\begin{equation}\label{eq:a}
D(2n)=4n + a, a\in\{-1,0,1\}.
\end{equation}
\begin{enumerate}[(1)]
\item
If $D(2n)=4n-1$, then $2n$ is almost perfect.
\item
If $D(2n)=4n$, then $2n$ is perfect.
\item
If $D(2n)=4n+1$, then $2n$ is quasi-perfect.
\end{enumerate}
\end{description}
